            # direction of extension is beyond min/max end points
            ends=[lo,hi]
            for e in ends:
                n_=(e[0]+1,e[1]+1) if diag=='m' else (e[0]+1,e[1]-1)
                while 0<=n_[0]<H and 0<=n_[1]<W and orig[n_[0]][n_[1]]==bg and orig[n_[0]][n_[1]]!=col:
